/**
 * Loader for `robotics_wasm`, the compiled Rust the widgets call.
 *
 * `lib/wasm/pkg/` is generated by `npm run wasm` (wasm-bindgen `--target web`) from
 * `crates/robotics_wasm`; nothing here is a port of that code. In the browser the module
 * is fetched from `public/wasm/`, under the same base path as the rest of the site.
 */
import init, * as bindings from './wasm/pkg/robotics_wasm.js';

export type Robotics = typeof bindings;

const BASE = (process.env.NEXT_PUBLIC_BASE_PATH ?? '').replace(/\/+$/, '');

let loading: Promise<Robotics> | null = null;

/** Fetch and instantiate the module once; every widget shares the instance. */
export function loadRobotics(): Promise<Robotics> {
  loading ??= init({ module_or_path: `${BASE}/wasm/robotics_wasm_bg.wasm` }).then(() => bindings);
  return loading;
}
